import{_ as t,o as a,c as i,ah as n}from"./chunks/framework.DDXs_i7t.js";const p=JSON.parse('{"title":"March 24, 2026, 8:30 PM: \\"Grapevine\\", Laptop Detention, and the \\"Black Cell Member\\"","description":"","frontmatter":{},"headers":[],"relativePath":"en/logbuch/2026-03-24-prozess-update-abend.md","filePath":"en/logbuch/2026-03-24-prozess-update-abend.md"}'),o={name:"en/logbuch/2026-03-24-prozess-update-abend.md"};function r(s,e,l,c,h,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="march-24-2026-8-30-pm-grapevine-laptop-detention-and-the-black-cell-member" tabindex="-1">March 24, 2026, 8:30 PM: &quot;Grapevine&quot;, Laptop Detention, and the &quot;Black Cell Member&quot; <a class="header-anchor" href="#march-24-2026-8-30-pm-grapevine-laptop-detention-and-the-black-cell-member" aria-label="Permalink to &quot;March 24, 2026, 8:30 PM: &quot;Grapevine&quot;, Laptop Detention, and the &quot;Black Cell Member&quot;&quot;">​</a></h1><p>Today&#39;s trial at the Linz Regional Court ended just minutes ago. While August Wöginger (the man who, according to his CV, has never worked &quot;outside&quot; in the free market) continues to plead his innocence, nearly a dozen witnesses painted a grim picture of the Upper Austrian tax administration.</p><h2 id="evening-forensic-insights" tabindex="-1">Evening Forensic Insights: <a class="header-anchor" href="#evening-forensic-insights" aria-label="Permalink to &quot;Evening Forensic Insights:&quot;">​</a></h2><ol><li><strong>The &quot;Grapevine&quot; as Law:</strong> Numerous officials confirmed that the appointment for the Braunau tax office was an open secret. The ÖVP mayor was a certainty long before the hearing commission ever met. Qualification? A side issue. Party membership? Decisive.</li><li><strong>The &quot;Strange&quot; Ticker Ban:</strong> Judge Melanie Halbig today prohibited all live reporting. Criminal law expert Robert Kert (WU Vienna) described this in <em>Der Standard</em> as legally baseless (&quot;strange&quot;). There is no legal foundation in the Code of Criminal Procedure (StPO) for such a ban.</li><li><strong>The Investigative Question:</strong> When a judge locks out the public without a legal basis while incriminating witnesses testify against the ÖVP, we must ask in the archive: Are we dealing with a <strong>&quot;black cell member&quot;</strong> (political operative)? Does the ban serve to protect the witnesses or the defendant from the truth?</li><li><strong>Satirical Escalation:</strong> <em>Die Tagespresse</em> is already reporting on Cobra special forces operations against journalists&#39; laptops, which were taken into &quot;detention.&quot; A fitting image for the absurd fear of facts in the courtroom.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion: <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion:&quot;">​</a></h2><p>Wöginger is fighting for his political survival while his successor Hattmannsdorfer is already waiting in the wings. The trial reveals not only political patronage but also a judicial dynamic that we must observe very closely.</p><hr><p><em>Preview: Friday continues. The archive stays awake.</em></p>',8)])])}const g=t(o,[["render",r]]);export{p as __pageData,g as default};
